steps.action:
curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "query {
      issues(first: 20, filter: { search: { query: \"login redirect\" } }) {
        nodes {
          id
          title
          url
          identifier
          team { id name key }
          creator { id name }
          assignee { id name }
        }
      }
    }"
  }'
